public static Queue<Integer> copy(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    Queue<Integer> result = new Queue<Integer>();
    while (!q.isEmpty()) {
        int x = q.remove();
        result.insert(x);
        temp.insert(x);
    }
    // מחזירים את האיברים — התור חוזר להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return result;
}

public static boolean contains(Queue<Integer> q, int x) {
    Queue<Integer> temp = new Queue<Integer>();
    boolean found = false;
    while (!q.isEmpty()) {
        int y = q.remove();
        if (y == x) {
            found = true;
        }
        temp.insert(y);
    }
    // מחזירים את האיברים — התור חוזר להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
    return found;
}

exercise.mainCode:
Queue<Integer> q = new Queue<Integer>();
q.insert(5);
q.insert(1);
q.insert(8);
Queue<Integer> c = copy(q);
System.out.println("סעיף א: " + c + " המקורי: " + q);
System.out.println("סעיף ב: " + contains(q, 8) + " " + contains(q, 2));

